using Scellecs.Morpeh.Native;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;
using UnityEngine;
using ZE.MechBattle.Ecs;
using ZE.MechBattle.Navigation;

namespace ZE.MechBattle.Views
{
    // partially generated by Qwen
    [BurstCompile]
    public struct HexVisibilityCheckJob : IJob
    {
        [ReadOnly] public NativeFilter HexesFilter;
        [ReadOnly] public CameraFrustrum2D CameraData;
        [ReadOnly] public NativeStash<HexComponent> HexComponents;
        public NativeStash<HexSectorsVisibilityMaskComponent> HexVisibilityMasks;

        public float HexEdge;

        public void Execute()
        {
            var verticesPreset = new HexVerticesPreset(HexEdge);
            var offset0 = verticesPreset[0];
            var offset1 = verticesPreset[1];
            var offset2 = verticesPreset[2];
            var offset3 = verticesPreset[3];
            var offset4 = verticesPreset[4];
            var offset5 = verticesPreset[5];

            for (int i = 0; i < HexesFilter.length; i++)
            {
                var hexEntity = HexesFilter[i];
                var hexCoord = HexComponents.Get(hexEntity).Coord;
                float2 center = HexMath.HexToWorld(hexCoord, HexEdge);

                // 1. Вычисляем видимость 6 вершин как 0 или 1 (строго без ветвлений)
                int v0 = IsVisibleInt(center + offset0);
                int v1 = IsVisibleInt(center + offset1);
                int v2 = IsVisibleInt(center + offset2);
                int v3 = IsVisibleInt(center + offset3);
                int v4 = IsVisibleInt(center + offset4);
                int v5 = IsVisibleInt(center + offset5);

                // 2. Упаковываем в 6-битное число: бит i = 1, если вершина i видна
                int V = v0 | (v1 << 1) | (v2 << 2) | (v3 << 3) | (v4 << 4) | (v5 << 5);

                // 3. Рассчитываем маску секторов. 
                // Сдвиг вправо на 1 (V >> 1) накладывает видимость вершины i на сектор i.
                // (V & 1) << 5 обрабатывает циклический переход: вершина 0 (TR) также влияет на сектор 5 (TL-TR).
                int edgeMask = V | ((V >> 1) | ((V & 1) << 5));

                // 4. Если центр виден (centerVis == 1), умножение на 63 даст 63 (0b111111).
                // Если не виден (centerVis == 0), даст 0. Побитовое ИЛИ объединяет результаты.
                int centerVis = IsVisibleInt(center);
                int mask = edgeMask | (centerVis * 63);

                HexVisibilityMasks.Get(hexEntity).Value = mask;
            }
        }

        // Оптимизированная безветочная (branchless) проверка попадания точки во фрустум
        // generated by GoogleAI
        private int IsVisibleInt(float2 point)
        {
            // 1. Переводим 2D-точку гекса в 3D-точку на плоскости земли
            float3 worldPos = new float3(point.x, 0f, point.y);
            float3 dir = worldPos - CameraData.CameraPos;

            // 2. Переводим в пространство камеры (View Space) — всего 3 dot-продукта!
            float z = math.dot(dir, CameraData.CameraForward); // Глубина вдоль луча камеры
            float x = math.dot(dir, CameraData.CameraRight);   // Смещение вправо
            float y = math.dot(dir, CameraData.CameraUp);      // Смещение вверх

            // 3. Считаем допустимые границы пирамиды видимости на текущей глубине z
            // Умножаем Padding на косинус/секанс угла, чтобы запас работал по нормали к краю экрана
            float maxX = z * CameraData.TanHalfHorizFov + CameraData.Padding;
            float maxY = z * CameraData.TanHalfVertFov + CameraData.Padding;

            // 4. Проверяем попадание в пирамиду (строго branchless)
            bool inDepth = (z >= CameraData.NearClip - CameraData.Padding) & (z <= CameraData.FarClip + CameraData.Padding);
            bool inHoriz = math.abs(x) <= maxX;
            bool inVert = math.abs(y) <= maxY;

            return math.select(0, 1, inDepth & inHoriz & inVert);
        }
    }
}
